--comment: CURRENT definition of view direct.appraisers. GENERATED by bin/export-schema.ps1: do not edit. Change it with a script in liquibase/direct/scripts/, apply, then regenerate.
CREATE OR REPLACE VIEW direct.appraisers
(
    `Appraiser_ID` Int32,
    `Appraiser` Nullable(String),
    `Appraiser_Company_Name` Nullable(String),
    `Appraiser_Address` Nullable(String),
    `Appraiser_City` Nullable(String),
    `Appraiser_State` Nullable(String),
    `Appraiser_Zip` Nullable(String),
    `Appraiser_Phone` Nullable(String),
    `Appraiser_Alt._Phone` Nullable(String),
    `Appraiser_Email` Nullable(String),
    `Appraiser_Fax` Nullable(String),
    `EIN_SSN` Nullable(String),
    `Insurance_Company` Nullable(String),
    `Ins._Exp_Date` Nullable(DateTime64(3)),
    `Ins._Coverage_Amount` Nullable(Decimal(18, 2)),
    `FHA` Nullable(Bool),
    `VA` Nullable(Bool),
    `Certification_Type` Nullable(String),
    `Appraisal_Software_Used` Nullable(String),
    `Appraiser_Status` Nullable(String),
    `Commercial` Nullable(Bool),
    `Appraiser_Notes` Nullable(String),
    `Appraiser_Added_On` DateTime64(3),
    `Appraiser_Added_By` Nullable(String),
    `Appraiser_Last_Updated_On` Nullable(DateTime64(3)),
    `Appraiser_Last_Updated_By` Nullable(String),
    `Is_Reviewer` Nullable(Bool),
    `Bank_Account_Holder` Nullable(String),
    `Bank_Name` Nullable(String),
    `Bank_City` Nullable(String),
    `Bank_State` Nullable(String),
    `Bank_Routing_Number` Nullable(String),
    `Account_Type` Nullable(String),
    `Account_Number` Nullable(String),
    `Appraisal_Fee_Percentage` Nullable(Decimal(18, 2)),
    `Review_Fee_Percentage` Nullable(Decimal(18, 2)),
    `Review_Fee_Amount` Nullable(Decimal(18, 2)),
    `Chase_Approved` Nullable(Bool),
    `Flagstar_Approved` Nullable(Bool),
    `Orders_Declined` Int32,
    `Vendor_Type_ID` Nullable(Int32),
    `Average Turntime` Nullable(Int32),
    `Vendor_Type_Name` Nullable(String),
    `Accounting_System_ID` Nullable(String),
    `Vendor_Score` Nullable(Int32),
    `tenant` LowCardinality(String)
)
DEFINER = default SQL SECURITY DEFINER
AS WITH
    declines AS
    (
        SELECT
            tenant,
            vendor_id,
            count() AS cnt
        FROM analytics.vendor_declines
        FINAL
        GROUP BY
            tenant,
            vendor_id
    ),
    turntime AS
    (
        SELECT
            _tenant AS tenant,
            Assigned_To_Appraiser AS vendor_id,
            if(count(dateDiff('day', Assign_Date, Appraisal_File_Submitted_On)) = 0, NULL, intDiv(sum(dateDiff('day', Assign_Date, Appraisal_File_Submitted_On)), count(dateDiff('day', Assign_Date, Appraisal_File_Submitted_On)))) AS days
        FROM raw.appraisals
        FINAL
        WHERE (__deleted = 'false') AND (Assigned_To_Appraiser IS NOT NULL) AND (Appraisal_Status_ID IN (6, 8))
        GROUP BY
            _tenant,
            Assigned_To_Appraiser
    )
SELECT
    v.vendor_id AS Appraiser_ID,
    v.vendor_name AS Appraiser,
    v.company_name AS Appraiser_Company_Name,
    v.address AS Appraiser_Address,
    v.city AS Appraiser_City,
    v.state_code AS Appraiser_State,
    v.zip AS Appraiser_Zip,
    v.phone1 AS Appraiser_Phone,
    v.phone2 AS `Appraiser_Alt._Phone`,
    v.email AS Appraiser_Email,
    v.fax AS Appraiser_Fax,
    v.ein AS EIN_SSN,
    v.insurance_company_name AS Insurance_Company,
    v.insurance_exp_date AS `Ins._Exp_Date`,
    v.insurance_coverage_amount AS `Ins._Coverage_Amount`,
    v.fha_certified AS FHA,
    v.va_certified AS VA,
    ct.name AS Certification_Type,
    sw.name AS Appraisal_Software_Used,
    st.name AS Appraiser_Status,
    v.commercial AS Commercial,
    v.other_details AS Appraiser_Notes,
    v.created_on AS Appraiser_Added_On,
    v.created_by AS Appraiser_Added_By,
    v.last_modified_on AS Appraiser_Last_Updated_On,
    v.last_modified_by AS Appraiser_Last_Updated_By,
    v.is_reviewer AS Is_Reviewer,
    v.bank_accountholder_name AS Bank_Account_Holder,
    v.bank_name AS Bank_Name,
    v.bank_city AS Bank_City,
    v.bank_state_code AS Bank_State,
    v.bank_routing_number AS Bank_Routing_Number,
    v.bank_account_type AS Account_Type,
    v.bank_account_number AS Account_Number,
    v.fee_rate AS Appraisal_Fee_Percentage,
    v.review_fee_rate AS Review_Fee_Percentage,
    v.default_review_fee AS Review_Fee_Amount,
    v.chase_approved AS Chase_Approved,
    v.flagstar_approved AS Flagstar_Approved,
    toInt32(ifNull(d.cnt, 0)) AS Orders_Declined,
    v.vendor_type_id AS Vendor_Type_ID,
    toNullable(toInt32(tt.days)) AS `Average Turntime`,
    vt.name AS Vendor_Type_Name,
    v.accounting_system_id AS Accounting_System_ID,
    v.score AS Vendor_Score,
    v.tenant AS tenant
FROM analytics.vendors AS v
FINAL
LEFT JOIN analytics.vendor_statuses AS st
FINAL ON (st.status_id = v.status_id) AND (st.tenant = v.tenant)
LEFT JOIN analytics.vendor_cert_types AS ct
FINAL ON (ct.cert_type_id = v.cert_type_id) AND (ct.tenant = v.tenant)
LEFT JOIN analytics.vendor_software AS sw
FINAL ON (sw.software_type_id = v.software_type_id) AND (sw.tenant = v.tenant)
LEFT JOIN analytics.vendor_types AS vt
FINAL ON (vt.vendor_type_id = v.vendor_type_id) AND (vt.tenant = v.tenant)
LEFT JOIN declines AS d ON (d.vendor_id = v.vendor_id) AND (d.tenant = v.tenant)
LEFT JOIN turntime AS tt ON (tt.vendor_id = v.vendor_id) AND (tt.tenant = v.tenant)
WHERE (v.is_deactivated = 0) AND (vt.is_active = 1)
SETTINGS join_use_nulls = 1;
--rollback empty
